            elif c == "/":
                tokens.append(("/", "/"))
                i += 1
            elif c == "*":
                if i + 1 < n and text[i + 1] == "*":
                    tokens.append(("**", "**"))
                    i += 2
                else:
                    tokens.append(("*", "*"))
                    i += 1
            elif c in DIGITS or c == ".":
                start = i
                has_digit = False

                while i < n and text[i] in DIGITS:
                    has_digit = True
                    i += 1

                if i < n and text[i] == ".":
