def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression using recursive descent parsing.

    Supported grammar:
      expression = term (('+' | '-') term)*
      term       = factor (('*' | '/') factor)*
      factor     = ('+' | '-') factor | power
      power      = atom ('**' factor)?
      atom       = number | '(' expression ')'

    Numbers are non-negative integer or decimal literals.
    """
    n = len(expr)
    pos = 0

    def is_digit(ch: str) -> bool:
        return "0" <= ch <= "9"

    def skip_whitespace() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expression() -> float:
        value = parse_term()
        skip_whitespace()

        while pos < n and expr[pos] in "+-":
            op = expr[pos]
            pos += 1

            rhs = parse_term()

            if op == "+":
                value += rhs
            else:
                value -= rhs

            skip_whitespace()

        return value

    def parse_term() -> float:
        value = parse_factor()
        skip_whitespace()

        while pos < n and expr[pos] in "*/":
            op = expr[pos]

            # A standalone '*' may be multiplication. If it is immediately
            # followed by another '*', this was not consumed by power(),
            # so the input is malformed.
            if op == "*" and pos + 1 < n and expr[pos + 1] == "*":
                raise ValueError("unexpected '**'")

            pos += 1
            rhs = parse_factor()

            if op == "*":
                value *= rhs
            else:
                value /= rhs

            skip_whitespace()

        return value

    def parse_factor() -> float:
        skip_whitespace()

        # Consume any leading unary + / - operators.
        sign = 1
        while pos < n and expr[pos] in "+-":
            if expr[pos] == "-":
                sign = -sign
            pos += 1
            skip_whitespace()

        # Unary operators in Python bind looser than ** but tighter than
        # * and /, and they bind to the whole following power expression.
        return sign * parse_power()

    def parse_power() -> float:
        base = parse_atom()
        skip_whitespace()

        # Right-associative exponentiation:
        # parse the right operand as a factor, which may itself contain **.
        if pos + 1 < n and expr[pos:pos + 2] == "**":
            pos += 2
            exponent = parse_factor()
            return base ** exponent

        return base

    def parse_atom() -> float:
        skip_whitespace()

        if pos >= n:
            raise ValueError("unexpected end of expression")

        ch = expr[pos]

        if is_digit(ch):
            return parse_number()

        if ch == "(":
            pos += 1
            skip_whitespace()

            if pos < n and expr[pos] == ")":
                raise ValueError("empty parentheses")

            value = parse_expression()
            skip_whitespace()

            if pos >= n or expr[pos] != ")":
                raise ValueError("missing closing parenthesis")

            pos += 1
            return value

        raise ValueError("unexpected character")

    def parse_number() -> float:
        start = pos

        if pos >= n or not is_digit(expr[pos]):
            raise ValueError("invalid number")

        pos += 1
        while pos < n and is_digit(expr[pos]):
            pos += 1

        if pos < n and expr[pos] == ".":
            pos += 1

            if pos >= n or not is_digit(expr[pos]):
                raise ValueError("invalid decimal literal")

            while pos < n and is_digit(expr[pos]):
                pos += 1

        try:
            return float(expr[start:pos])
        except ValueError as exc:
            raise ValueError("invalid number") from exc

    result = parse_expression()
    skip_whitespace()

    if pos != n:
        raise ValueError("unexpected characters at end of expression")

    return float(result)
